package com.gerenciadorrural.modules.herd.api;
import com.fasterxml.jackson.annotation.JsonIgnoreProperties; import com.fasterxml.jackson.databind.annotation.JsonDeserialize; import com.gerenciadorrural.modules.herd.application.*; import com.gerenciadorrural.modules.herd.domain.*; import com.gerenciadorrural.modules.organizations.api.ResolvedTenantContext; import com.gerenciadorrural.shared.tenancy.TenantContext; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/v1/herd") public class HerdMovementController {private final MoveCurrentFarmAnimals moves;public HerdMovementController(MoveCurrentFarmAnimals moves){this.moves=moves;}@PostMapping("/animals/{id}/movements") public ResponseEntity<HerdAnimalController.Item> one(@ResolvedTenantContext TenantContext c,@PathVariable UUID id,@RequestBody Request r){return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(HerdAnimalController.Item.from(moves.one(c,id,r.operationId(),r.expectedVersion(),r.destinationPaddockId(),r.occurredOn(),r.notes())));}@PostMapping("/movements/batch") public ResponseEntity<BatchResponse> batch(@ResolvedTenantContext TenantContext c,@RequestBody BatchRequest r){var x=moves.batch(c,r.operationId(),r.destinationPaddockId(),r.occurredOn(),r.notes(),r.animals());return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(BatchResponse.from(x));}@JsonIgnoreProperties(ignoreUnknown=false) @JsonDeserialize(using=HerdMovementRequestDeserializer.class) public record Request(UUID operationId,long expectedVersion,UUID destinationPaddockId,LocalDate occurredOn,String notes){}@JsonIgnoreProperties(ignoreUnknown=false) @JsonDeserialize(using=HerdBatchMovementRequestDeserializer.class) public record BatchRequest(UUID operationId,UUID destinationPaddockId,LocalDate occurredOn,String notes,List<MoveCurrentFarmAnimals.Animal> animals){} public record BatchResponse(String operationId,PaddockItem destinationPaddock,int movedCount,List<Version> animals){static BatchResponse from(MoveCurrentFarmAnimals.BatchResult x){return new BatchResponse(x.operationId().toString(),PaddockItem.from(x.destinationPaddock()),x.movedCount(),x.animals().stream().map(a->new Version(a.id().toString(),a.version())).toList());}}public record Version(String id,long version){}}
